#pragma once

#include "klyrdb/common/status.hpp"
#include "klyrdb/common/result.hpp"
#include "klyrdb/backup/backup_manifest.hpp"
#include <filesystem>
#include <vector>
#include <string>
#include <iosfwd>

namespace klyrdb {

/// Detailed diagnostic report generated by BackupVerifier.
struct BackupVerificationReport {
    bool is_valid{false};
    std::vector<std::string> checks_passed;
    std::vector<std::string> failures;
    std::vector<std::string> warnings;
    BackupManifest manifest;

    [[nodiscard]] size_t passed_count() const noexcept { return checks_passed.size(); }
    [[nodiscard]] size_t failure_count() const noexcept { return failures.size(); }
    [[nodiscard]] size_t warning_count() const noexcept { return warnings.size(); }

    void add_check(std::string name) { checks_passed.push_back(std::move(name)); }
    void add_failure(std::string reason) { is_valid = false; failures.push_back(std::move(reason)); }
    void add_warning(std::string warn) { warnings.push_back(std::move(warn)); }

    void print(std::ostream& os) const;
};

/// Standalone verification subsystem auditing backup manifests, file geometry,
/// bit-level component checksums, and storage/relational integrity.
class BackupVerifier {
public:
    BackupVerifier() = default;
    ~BackupVerifier() = default;

    /// Verifies a physical backup directory without restoring or modifying it.
    Result<BackupVerificationReport> verify(const std::filesystem::path& backup_path) const;
};

} // namespace klyrdb
